    /**
     * Method to retrieve the Household via an FindHouseholdQuery
     * @return 	query	FindHouseholdQuery
     */
    @SuppressWarnings("unused")
    public Household find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Household - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
